const descriptions={Refrigeradores:'Conservación confiable, organización inteligente y eficiencia para proteger los alimentos de toda la familia.',Cocinas:'Fabricación brasileña, quemadores de distintas potencias y hornos amplios para cocinar y hacer repostería.',Lavadoras:'Lavado potente y cuidado práctico de las prendas con tambor de acero inoxidable, control inteligente y secado de aire.'};
window.naihoCatalog=catalog;window.naihoDescriptions=descriptions;
function header(){return `<div class="topbar">Tecnología brasileña para hogares latinoamericanos <span>•</span> Garantía regional</div><header class="header"><a class="logo" href="index.html">NAIHO<span></span></a><button class="menu" aria-label="Abrir menú" aria-expanded="false"><i></i><i></i><i></i></button><nav class="nav"><a href="index.html">Inicio</a><a href="refrigeradores.html">Refrigeradores</a><a href="cocinas.html">Cocinas</a><a href="lavadoras.html">Lavadoras</a><a href="index.html#historia">Historia</a><a href="index.html#servicio">Servicio técnico</a><a href="index.html#contacto" class="nav-cta">Contáctanos</a></nav></header>`}
function footer(){return `<footer class="page-footer"><a class="logo light-logo" href="index.html">NAIHO<span></span></a><p>Electrodomésticos pensados para acompañar tu vida.</p><div><a href="index.html">Inicio</a><a href="refrigeradores.html">Refrigeradores</a><a href="cocinas.html">Cocinas</a><a href="index.html#servicio">Servicio técnico</a></div><small>© 2026 NAIHO. Todos los derechos reservados.</small></footer>`}
function card(p){return `<article class="product-card"><div class="product-image real-photo"><img src="${p.image}" alt="${p.name}"></div><div class="product-info"><small>${p.category.toUpperCase()}</small><h3>${p.name}</h3><p>${descriptions[p.category]}</p><div class="chips">${p.specs.slice(0,2).map(s=>`<span>${s}</span>`).join('')}</div><a class="card-link" href="producto.html?id=${p.id}">Ver características →</a></div></article>`}
function initMenu(){const m=document.querySelector('.menu'),n=document.querySelector('.nav');m?.addEventListener('click',()=>{const o=n.classList.toggle('open');m.setAttribute('aria-expanded',o)})}
const type=document.body.dataset.page;
if(type==='category'){const key=document.body.dataset.category,category=key==='cocinas'?'Cocinas':key==='lavadoras'?'Lavadoras':'Refrigeradores',items=catalog.filter(p=>p.category===category),titles={Cocinas:'14 cocinas para cada forma de cocinar.',Refrigeradores:'10 refrigeradores para cada tipo de hogar.',Lavadoras:'Lavado inteligente para cuidar cada prenda.'};document.body.innerHTML=header()+`<main><section class="sub-hero"><div><div class="breadcrumbs"><a href="index.html">Inicio</a><span>›</span><span>${category}</span></div><h1>${titles[category]}</h1><p>${descriptions[category]}</p></div></section><section class="category-wrap"><div class="category-intro"><h2>${items.length} ${items.length===1?'modelo disponible':'modelos disponibles'}</h2><p>Selecciona un modelo para abrir su ficha completa y conocer sus funciones.</p></div><div class="product-grid catalog-grid">${items.map(card).join('')}</div></section></main>`+footer();initMenu()}
if(type==='detail'){const id=new URLSearchParams(location.search).get('id')||document.body.dataset.product,p=catalog.find(x=>x.id===id)||catalog[0],labels=p.category==='Cocinas'?['Configuración','Ancho','Horno','Acabado']:p.category==='Lavadoras'?['Tipo de carga','Tambor','Tecnología','Secado']:['Capacidad','Formato','Tecnología','Característica'],features=p.category==='Cocinas'?['Quemadores con potencia adaptada a cada preparación','Horno amplio con cocción uniforme para repostería','Encendido práctico y superficies de fácil limpieza','Parrillas resistentes para uso cotidiano']:p.category==='Lavadoras'?['Tambor de acero inoxidable resistente y fácil de cuidar','Smart Wash con sistema Fuzzy para un lavado práctico','Tecnología de filtro de residuos','Controles de nivel de agua, reserva, programación y pausa']:['Distribución uniforme del frío para mejor conservación','Organización interior según su capacidad','Funcionamiento eficiente y silencioso','Tecnología de refrigeración indicada para este modelo'],gallery=p.gallery||[p.image];document.title=p.name+' | NAIHO';document.body.innerHTML=header()+`<main class="detail"><div class="back-row"><button class="back-button" onclick="history.back()">← Volver atrás</button><a href="index.html">Ir al inicio</a><span>›</span><a href="${p.category.toLowerCase()}.html">${p.category}</a></div><div class="detail-grid"><div><div class="detail-photo"><img id="main-product-image" src="${p.image}" alt="${p.name}"></div>${gallery.length>1?`<div class="product-gallery">${gallery.map((src,i)=>`<button class="gallery-thumb${i===0?' active':''}" data-src="${src}" aria-label="Ver foto ${i+1}"><img src="${src}" alt="Vista ${i+1} de ${p.name}"></button>`).join('')}</div>`:''}</div><div class="detail-copy"><span class="kicker">${p.category.toUpperCase()} · NAIHO</span><h1>${p.name}</h1><p class="lead">${descriptions[p.category]}</p><div class="spec-grid">${p.specs.map((s,i)=>`<div class="spec"><small>${labels[i]}</small><b>${s}</b></div>`).join('')}</div><h3>Características principales</h3><ul class="feature-list">${features.map(f=>`<li>${f}</li>`).join('')}</ul><div class="detail-actions"><a class="button primary" href="https://wa.me/591" target="_blank" rel="noopener">Consultar disponibilidad →</a><a class="button secondary" href="${p.category.toLowerCase()}.html">Ver más modelos</a></div><p class="mini-note">Las especificaciones pueden variar según el país y distribuidor.</p></div></div></main>`+footer();initMenu();document.querySelectorAll('.gallery-thumb').forEach(btn=>btn.addEventListener('click',()=>{document.querySelector('#main-product-image').src=btn.dataset.src;document.querySelectorAll('.gallery-thumb').forEach(x=>x.classList.remove('active'));btn.classList.add('active')}))}
